          details: item.namaPengeluaran || item.keterangan || 'Operasional Lainnya (Utilitas/Lab)',
          qty: 1,
          unit: item.satuan || item.kategori || 'Bulan',
          unitPrice: price,
          totalPrice: item.jumlahBiaya || price,
